// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;

    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(
        address caller,
        address requester,
        bytes32 digest,
        uint256 utxoSize,
        bytes memory redeemerOutputScript,
        uint256 requestedFee,
        bytes memory outpoint
    ) public {
        vm.assume(caller != address(0));

        // The implicit owner of C is address(0); only it can register loggers.
        vm.prank(address(0));
        c.setApprovedLogger(caller, true);

        vm.prank(caller);
        bool ok = c.logRedemptionRequested(
            requester,
            digest,
            utxoSize,
            redeemerOutputScript,
            requestedFee,
            outpoint
        );

        assertTrue(ok);
    }
}
